			for (const param of params) if (!/:\s*\w/.test(param)) violations.push({
				file: filePath,
				type: "missing_sig",
				detail: `函数 ${match[1]}() 的参数 "${param}" 缺少类型标注。函数签名的参数和返回值必须显式声明类型。`
			});
			const returnMatch = code.slice(match.index + match[0].length).match(/^\s*(:\s*(\w+[\w<>[\]|&, ]*))?\s*{/);
			if (returnMatch && !returnMatch[1]) violations.push({
				file: filePath,
				type: "missing_sig",
				detail: `函数 ${match[1]}() 缺少返回值类型标注。参数和返回值类型必须显式声明。`
			});
